<script setup lang="tsx">
import { computed, ref, onMounted } from "vue";
import { useRoute } from "vue-router";
import router from "@/router";
import {
  GetContestClone,
  GetContestEdit,
  GetContestImageToken,
  ParseContest,
  PostContestCreate,
  PostContestEdit,
  GetContestReplayList,
  GetContestReplayEligible,
  PostContestReplayCreate,
  PostContestReplayUpdate,
  PostContestReplayDelete,
  PostContestReplayImportPreview,
  PostContestReplayImportConfirm,
  ParseContestReplay,
  ParseContestReplayEligible,
  ParseContestReplayImportPreview,
} from "@/apis/contest.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";
import type {
  ContestEditRequest,
  ContestView,
  ContestMember,
  ContestReplay,
  ContestReplayRaw,
  ContestReplayEligible,
  ContestReplayEligibleRaw,
  ContestReplayImportPreview,
  ContestReplayImportMapItem,
} from "@/types/contest.ts";
import {
  REPLAY_ALIAS_CONFIRM_TEXT,
  formatEligibleOptionLabel,
  formatReplayProblemMatched,
  isEligibleLinked,
  contestProblemLabel,
  buildSampleReplayCsv,
} from "@/views/contest/contest-replay-common.ts";
import ParseProblemList from "@/components/problem/ParseProblemList.vue";
import ParseUserList from "@/components/user/ParseUserList.vue";
import { GetSecondFromDuration, GetTimeStringBySeconds } from "@/time/library.ts";
import { HandleR2ImageUpload, UploadImageCallbackUrl } from "@/util/md-editor-v3.ts";
import { saveAs } from "file-saver";

const route = useRoute();
const { globalProperties } = useCurrentInstance();

const webStyleStore = useWebStyleStore();
const { isMobile } = useBreakpoint();

const editorToolbarsExclude = computed(() => {
  if (isMobile.value) {
    return ["mermaid", "katex", "table", "sub", "sup", "strikeThrough", "pageFullscreen"];
  }
  return [];
});

const contestId = ref(0);
const contestLoading = ref(false);
const isSaving = ref(false);
const editTab = ref("1");

const showDialog = ref(false);

// ---------- 回放关联 Tab：已关联列表 + 候选选择器（仅编辑态展示，新建比赛流程隐藏） ----------
const replayList = ref<ContestReplay[]>([]);
const eligibleList = ref<ContestReplayEligible[]>([]);
const replayLoading = ref(false);
const replaySubmitting = ref(false);
const eligibleSelectValue = ref<number | undefined>(undefined);
const aliasConfirmVisible = ref(false);
const pendingAliasSourceId = ref(0);
const deleteConfirmVisible = ref(false);
const pendingDeleteReplay = ref<ContestReplay | null>(null);

// ---------- 榜单文件导入：上传 → 预览（题目映射 / 告警 / 标题）→ 确认生成回放 ----------
const fileInput = ref<HTMLInputElement | null>(null);
const importPreview = ref<ContestReplayImportPreview | null>(null);
const importMapping = ref<Record<number, number>>({});
const importTitle = ref("");
const importConfirmVisible = ref(false);

const replayColumns = [
  { colKey: "title", title: "标题", minWidth: 160 },
  { colKey: "sourceTitle", title: "源比赛标题", minWidth: 160 },
  { colKey: "playerCount", title: "选手数", width: 90, align: "center" as const },
  { colKey: "problemMatched", title: "题目匹配", width: 130, align: "center" as const },
  { colKey: "isAlias", title: "别名标记", width: 90, align: "center" as const },
  { colKey: "enabled", title: "启停", width: 80, align: "center" as const },
  { colKey: "operation", title: "操作", width: 90, align: "center" as const },
];

const contestData = ref<ContestView | null>(null);

const contestEditForm = ref({
  title: "",
  openTime: [] as (Date | string)[],
  private: true,
  password: "",
  problems: [] as number[],
  members: [] as ContestMember[],
  description: "",
  notification: "",
  lockRankDuration: 0,
  alwaysLock: true,
  submitAnytime: false,
});

const parseDialogTitle = ref<string>("");
const textareaValue = ref("");
const parseFunction = null as (() => Promise<void>) | null;
const isParsing = ref(false);

const handleParse = async () => {
  isParsing.value = true;
  if (parseFunction) {
    await parseFunction();
  }
  showDialog.value = false;
  isParsing.value = false;
};

const handleUploadImg = async (files: File[], callback: (urls: UploadImageCallbackUrl[]) => void) => {
  isSaving.value = true;
  await HandleR2ImageUpload(files, callback, globalProperties, () => {
    return GetContestImageToken(contestId.value);
  });
  isSaving.value = false;
};

const handleClickCreate = async () => {
  isSaving.value = true;

  try {
    const postData = {
      title: contestEditForm.value.title,
      description: contestEditForm.value.description,
      notification: contestEditForm.value.notification,
      lock_rank_duration: contestEditForm.value.lockRankDuration,
      always_lock: contestEditForm.value.alwaysLock,
      problems: contestEditForm.value.problems,
      members: contestEditForm.value.members,
      private: contestEditForm.value.private,
      password: contestEditForm.value.password,
      submit_anytime: contestEditForm.value.submitAnytime,
    } as ContestEditRequest;
    if (contestEditForm.value.openTime[0]) {
      postData.start_time = new Date(contestEditForm.value.openTime[0]);
    }
    if (contestEditForm.value.openTime[1]) {
      postData.end_time = new Date(contestEditForm.value.openTime[1]);
    }
    const res = await PostContestCreate(postData);

    isSaving.value = true;

    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }

    if (res.data != undefined) {
      await router.push({
        name: "contest-detail",
        params: { contestId: res.data },
      });
    }

    ShowTextTipsSuccess(globalProperties, "创建成功");
  } finally {
    isSaving.value = false;
  }
};

const handleClickSave = async () => {
  isSaving.value = true;

  try {
    const postData = {
      id: Number(contestId.value),
      title: contestEditForm.value.title,
      notification: contestEditForm.value.notification,
      lock_rank_duration: contestEditForm.value.lockRankDuration,
      always_lock: contestEditForm.value.alwaysLock,
      problems: contestEditForm.value.problems,
      members: contestEditForm.value.members,
      private: contestEditForm.value.private,
      password: contestEditForm.value.password,
      submit_anytime: contestEditForm.value.submitAnytime,
      description: contestEditForm.value.description,
    } as ContestEditRequest;
    if (contestEditForm.value.openTime[0]) {
      postData.start_time = new Date(contestEditForm.value.openTime[0]);
    }
    if (contestEditForm.value.openTime[1]) {
      postData.end_time = new Date(contestEditForm.value.openTime[1]);
    }
    const res = await PostContestEdit(postData);

    isSaving.value = true;

    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }

    if (contestData.value) {
      if (res.data.description != undefined) {
        contestEditForm.value.description = res.data.description;
      }
      if (res.data.update_time != undefined) {
        contestData.value.modifyTime = new Date(res.data.update_time).toLocaleString();
      }
    }

    ShowTextTipsSuccess(globalProperties, "保存成功");
  } finally {
    isSaving.value = false;
  }
};

const loadDescriptionEditor = (description: string) => {
  contestEditForm.value.description = description;
  contestLoading.value = false;
};

const loadContest = async () => {
  const res = await GetContestEdit(contestId.value);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    console.error("contest get failed", res.code);
    await router.push({ name: "contest-list" });
    return;
  }

  const contest = res.data.contest;

  contestData.value = ParseContest(contest);

  contestEditForm.value.title = contest.title;
  contestEditForm.value.openTime = [] as (Date | string)[];
  if (contest.start_time) {
    contestEditForm.value.openTime.push(new Date(contest.start_time));
  } else {
    contestEditForm.value.openTime.push(""); // 默认开始时间为当前时间
  }
  if (contest.end_time) {
    contestEditForm.value.openTime.push(new Date(contest.end_time));
  } else {
    contestEditForm.value.openTime.push(""); // 默认结束时间为当前时间加一天
  }
  contestEditForm.value.private = contest.private;
  contestEditForm.value.password = contest.password || "";
  contestEditForm.value.description = contest.description || "";
  contestEditForm.value.notification = contest.notification || "";

  contestEditForm.value.problems = contest.problems;
  contestEditForm.value.members = contest.members;

  if (contest.lock_rank_duration) {
    contestEditForm.value.lockRankDuration = GetSecondFromDuration(contest.lock_rank_duration);
  } else {
    contestEditForm.value.lockRankDuration = 0;
  }
  contestEditForm.value.alwaysLock = contest.always_lock;

  contestEditForm.value.submitAnytime = contest.submit_anytime;

  webStyleStore.setTitle(contest.title + " - " + webStyleStore.getTitle);

  let contestDescription = "";
  if (contest.description) {
    contestDescription = contest.description as string;
  }

  loadDescriptionEditor(contestDescription);
};

const loadCloneContest = async (cloneContestId: number) => {
  const res = await GetContestClone(cloneContestId);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    loadDescriptionEditor("");
    return;
  }
  const contest = res.data.contest;

  contestEditForm.value.title = contest.title;

  contestEditForm.value.problems = contest.problems;

  if (contest.lock_rank_duration) {
    contestEditForm.value.lockRankDuration = GetSecondFromDuration(contest.lock_rank_duration);
  } else {
    contestEditForm.value.lockRankDuration = 0;
  }
  contestEditForm.value.alwaysLock = contest.always_lock;
  loadDescriptionEditor("");
};

// ---------- 回放关联 Tab 数据加载与交互 ----------

const loadReplayList = async () => {
  if (!contestId.value) return;
  replayLoading.value = true;
  try {
    const res = await GetContestReplayList(contestId.value);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    replayList.value = (res.data as ContestReplayRaw[]).map((item) => ParseContestReplay(item));
  } finally {
    replayLoading.value = false;
  }
};

const loadEligibleList = async () => {
  if (!contestId.value) return;
  const res = await GetContestReplayEligible(contestId.value);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    return;
  }
  eligibleList.value = (res.data as ContestReplayEligibleRaw[]).map((item) => ParseContestReplayEligible(item));
};

const refreshReplayPanel = async () => {
  await Promise.all([loadReplayList(), loadEligibleList()]);
};

const eligibleCandidateById = (sourceContestId: number) =>
  eligibleList.value.find((candidate) => candidate.contestId === sourceContestId);

const doCreateReplay = async (sourceContestId: number) => {
  replaySubmitting.value = true;
  try {
    const res = await PostContestReplayCreate(contestId.value, sourceContestId);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "关联成功");
    await refreshReplayPanel();
  } finally {
    replaySubmitting.value = false;
    eligibleSelectValue.value = undefined;
  }
};

const handleEligibleChange = async (value: unknown) => {
  const sourceContestId = Number(value);
  if (!sourceContestId) return;
  const candidate = eligibleCandidateById(sourceContestId);
  if (!candidate || isEligibleLinked(candidate)) return;
  if (candidate.isAlias) {
    // 别名候选：本体与本场已关联回放完全相同，创建前弹窗提示，确认后才落关联
    pendingAliasSourceId.value = sourceContestId;
    aliasConfirmVisible.value = true;
    return;
  }
  await doCreateReplay(sourceContestId);
};

const handleAliasConfirm = async () => {
  const sourceContestId = pendingAliasSourceId.value;
  pendingAliasSourceId.value = 0;
  if (sourceContestId > 0) {
    await doCreateReplay(sourceContestId);
  }
  aliasConfirmVisible.value = false;
};

// 别名提示弹窗取消：清空待确认候选与选择器残留值，避免同一项无法再次触发选中
const handleAliasCancel = () => {
  pendingAliasSourceId.value = 0;
  eligibleSelectValue.value = undefined;
};

const handleToggleReplay = async (replay: ContestReplay, enabled: boolean) => {
  const res = await PostContestReplayUpdate(replay.id, undefined, enabled);
  if (res.code !== 0) {
    ShowErrorTips(globalProperties, res.code);
    // 失败回滚：刷新列表恢复后端实际启停态
    await loadReplayList();
    return;
  }
  replay.enabled = enabled;
  ShowTextTipsSuccess(globalProperties, enabled ? "已启用" : "已停用");
};

const handleRemoveClick = (replay: ContestReplay) => {
  pendingDeleteReplay.value = replay;
  deleteConfirmVisible.value = true;
};

const handleDeleteConfirm = async () => {
  const replay = pendingDeleteReplay.value;
  deleteConfirmVisible.value = false;
  if (!replay) return;
  replaySubmitting.value = true;
  try {
    const res = await PostContestReplayDelete(replay.id);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "已移除关联");
    pendingDeleteReplay.value = null;
    await refreshReplayPanel();
  } finally {
    replaySubmitting.value = false;
  }
};

// 当前比赛题目数：用于示例 CSV 生成与兜底题目列数
const currentProblemCount = computed(() => contestData.value?.problems?.length ?? 0);

// 下载示例榜单 CSV：按本场题目数生成 A/B/C… 列与样例选手
const handleDownloadSampleCsv = () => {
  const problemCount = Math.max(currentProblemCount.value, 1);
  const csv = buildSampleReplayCsv(problemCount);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  saveAs(blob, `replay-standings-sample-${contestId.value}.csv`);
};

// 选择文件后上传解析，进入预览；失败走错误提示，不打开弹窗
const handleImportFileChange = async (e: Event) => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  if (!file) return;
  replaySubmitting.value = true;
  try {
    const res = await PostContestReplayImportPreview(contestId.value, file);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    const preview = ParseContestReplayImportPreview(res.data);
    importPreview.value = preview;
    importTitle.value = preview.titleSuggestion || "";
    // 默认映射：题目顺序对齐（后端已给 problem_map），回退到序号对齐
    const mapping: Record<number, number> = {};
    if (preview.problemMap.length > 0) {
      for (const item of preview.problemMap) {
        mapping[item.sourceIndex] = item.targetIndex;
      }
    } else {
      preview.sourceProblems.forEach((_, i) => {
        mapping[i] = i + 1;
      });
    }
    importMapping.value = mapping;
    importConfirmVisible.value = true;
  } catch (err) {
    console.error("replay import preview failed", err);
  } finally {
    replaySubmitting.value = false;
    if (input) input.value = "";
  }
};

// 预览弹窗确认：按题目映射生成回放关联，成功后刷新回放面板
const handleImportConfirm = async () => {
  const preview = importPreview.value;
  if (!preview) return;
  const problemMap: ContestReplayImportMapItem[] = Object.entries(importMapping.value).map(([sourceIndex, targetIndex]) => ({
    sourceIndex: Number(sourceIndex),
    targetIndex,
  }));
  replaySubmitting.value = true;
  try {
    const res = await PostContestReplayImportConfirm(contestId.value, importTitle.value, preview.previewId, problemMap);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }
    ShowTextTipsSuccess(globalProperties, "榜单回放已生成");
    handleImportCancel();
    await refreshReplayPanel();
  } finally {
    replaySubmitting.value = false;
  }
};

// 取消预览：关闭弹窗并清空解析态，不落任何关联
const handleImportCancel = () => {
  importConfirmVisible.value = false;
  importPreview.value = null;
  importMapping.value = {};
  importTitle.value = "";
};

onMounted(async () => {
  if (Array.isArray(route.params.contestId)) {
    contestId.value = Number(route.params.contestId[0]);
  } else {
    contestId.value = Number(route.params.contestId);
  }

  if (contestId.value) {
    contestLoading.value = true;
    await loadContest();
    // 编辑态加载成功后再拉回放关联列表与候选；加载失败已在 loadContest 内跳转列表页
    if (contestData.value) {
      await refreshReplayPanel();
    }
  } else {
    // 获取query是否包含contest_id
    if (route.query.contest_id) {
      const cloneContestId = Number(route.query.contest_id);
      await loadCloneContest(cloneContestId);
    } else {
      loadDescriptionEditor("");
    }
  }
});
</script>

<template>
  <t-loading :loading="contestLoading">
    <t-row>
      <t-col :span="isMobile ? 12 : 8">
        <div style="margin: 10px">
          <t-card class="sh-card">
            <t-tabs v-model="editTab">
              <t-tab-panel value="1" label="基础信息" style="padding: 10px">
                <t-form :model="contestEditForm" :label-align="isMobile ? 'top' : 'right'" label-width="150px">
                  <t-form-item label="标题">
                    <t-input v-model="contestEditForm.title" placeholder="比赛标题"></t-input>
                  </t-form-item>
                  <t-form-item label="通知">
                    <t-input v-model="contestEditForm.notification" placeholder="会更为醒目地提醒"></t-input>
                  </t-form-item>
                  <t-form-item label="开启时间">
                    <t-date-range-picker
                      v-model="contestEditForm.openTime"
                      allow-input
                      clearable
                      format="YYYY-MM-DD HH:mm:ss"
                      :default-time="['00:00:00', '23:59:59']"
                    />
                  </t-form-item>
                  <t-form-item label="结束后提交">
                    <t-switch v-model="contestEditForm.submitAnytime">
                      <template #label="slotProps">{{ slotProps.value ? "允许" : "禁止" }}</template>
                    </t-switch>
                  </t-form-item>

                  <t-form-item label="锁榜时长">
                    <t-input-number v-model="contestEditForm.lockRankDuration" :min="0" :format="GetTimeStringBySeconds" auto-width></t-input-number>
                  </t-form-item>
                  <t-form-item label="自动解锁">
                    <t-switch v-model="contestEditForm.alwaysLock">
                      <template #label="slotProps">{{ slotProps.value ? "结束后仍锁榜" : "结束后解锁" }}</template>
                    </t-switch>
                  </t-form-item>

                  <t-form-item label="私有">
                    <t-switch v-model="contestEditForm.private" />
                  </t-form-item>
                  <t-form-item v-if="contestEditForm.private" label="密码">
                    <t-input
                      v-model="contestEditForm.password"
                      type="password"
                      autocomplete="current-password"
                      placeholder="请输入访问密码，留空代表关闭密码访问"
                    ></t-input>
                  </t-form-item>
                </t-form>
              </t-tab-panel>
              <t-tab-panel value="2" label="问题" style="padding: 10px">
                <ParseProblemList v-model="contestEditForm.problems" />
              </t-tab-panel>
              <t-tab-panel value="3" label="成员" style="padding: 10px">
                <ParseUserList v-model="contestEditForm.members" extra-field="contest_name" extra-column-title="比赛名称" />
              </t-tab-panel>
              <t-tab-panel v-if="contestId" value="4" label="回放关联" style="padding: 10px">
                <div class="dida-replay-toolbar">
                  <t-space size="small" wrap>
                    <t-select
                      v-model="eligibleSelectValue"
                      placeholder="选择已结束的源比赛关联回放"
                      auto-width
                      clearable
                      filterable
                      :disabled="replayLoading"
                      @change="handleEligibleChange"
                    >
                      <t-option
                        v-for="candidate in eligibleList"
                        :key="candidate.contestId"
                        :value="candidate.contestId"
                        :label="formatEligibleOptionLabel(candidate)"
                        :disabled="isEligibleLinked(candidate)"
                      />
                    </t-select>
                    <t-button variant="outline" :loading="replayLoading" @click="refreshReplayPanel">刷新</t-button>
                    <t-button variant="outline" :loading="replaySubmitting" @click="fileInput?.click()">上传榜单文件</t-button>
                    <t-button variant="text" @click="handleDownloadSampleCsv">下载示例 CSV</t-button>
                    <input ref="fileInput" type="file" accept=".csv,text/csv" style="display: none" @change="handleImportFileChange" />
                  </t-space>
                </div>
                <div style="overflow-x: auto; width: 100%">
                  <t-table
                    :data="replayList"
                    :columns="replayColumns"
                    row-key="id"
                    stripe
                    hover
                    :loading="replayLoading"
                    table-layout="auto"
                    size="small"
                    style="white-space: nowrap"
                  >
                    <template #title="{ row }">{{ row.title }}</template>
                    <template #sourceTitle="{ row }">{{ row.sourceTitle || "—" }}</template>
                    <template #playerCount="{ row }">{{ row.playerCount }} 人</template>
                    <template #problemMatched="{ row }">
                      <t-tag :theme="row.problemMatched ? 'success' : 'danger'" variant="light" size="small">
                        {{ formatReplayProblemMatched(row.problemMatched) }}
                      </t-tag>
                    </template>
                    <template #isAlias="{ row }">
                      <t-tag v-if="row.isAlias" theme="warning" variant="light" size="small">别名</t-tag>
                    </template>
                    <template #enabled="{ row }">
                      <t-switch
                        :value="row.enabled"
                        size="small"
                        @change="(value: boolean) => handleToggleReplay(row as ContestReplay, value)"
                      />
                    </template>
                    <template #operation="{ row }">
                      <t-button size="small" variant="text" theme="danger" @click="handleRemoveClick(row as ContestReplay)">
                        移除
                      </t-button>
                    </template>
                  </t-table>
                </div>
              </t-tab-panel>
            </t-tabs>
          </t-card>
        </div>
      </t-col>
      <t-col :span="isMobile ? 12 : 4">
        <div style="margin: 12px">
          <div class="dida-edit-container">
            <t-space v-if="contestId">
              <t-button theme="danger" :loading="isSaving" @click="handleClickSave">保存</t-button>
            </t-space>
            <t-space v-else>
              <t-button theme="danger" :loading="isSaving" @click="handleClickCreate">创建</t-button>
            </t-space>
          </div>
          <t-descriptions v-if="contestId" layout="vertical" :bordered="true">
            <t-descriptions-item label="创建时间">{{ contestData?.insertTime }}</t-descriptions-item>
            <t-descriptions-item label="编辑时间">{{ contestData?.modifyTime }}</t-descriptions-item>
